<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Autonomous Cave Runner</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      background: #06070d;
      overflow: hidden;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      font-family: 'Courier New', monospace;
    }
    canvas {
      box-shadow: 0 0 30px rgba(0, 255, 200, 0.2);
    }
  </style>
</head>
<body>
<canvas id="game"></canvas>

<script>
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');

  const WIDTH = 900;
  const HEIGHT = 500;
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  let distance = 0;
  const speed = 4;

  const ship = {
    x: 140,
    y: HEIGHT / 2,
    vy: 0,
    radius: 7,
    angle: 0
  };

  const particles = [];

  // Deterministic multi-frequency cave generator
  function getCeiling(x) {
    const worldX = x + distance;
    const n = Math.sin(worldX * 0.003) * 60 
            + Math.sin(worldX * 0.008) * 35 
            + Math.sin(worldX * 0.021) * 15;
    return 110 + n;
  }

  function getFloor(x) {
    const worldX = x + distance;
    const n = Math.sin(worldX * 0.0035 + 2.5) * 65 
            + Math.sin(worldX * 0.007 + 1.2) * 35 
            + Math.sin(worldX * 0.019 + 0.4) * 15;
    const floor = HEIGHT - (110 + n);
    // Ensure safe corridor height minimum
    return Math.max(floor, getCeiling(x) + 120);
  }

  function update() {
    distance += speed;

    // Autopilot Lookahead: Sample the safe corridor ahead
    const s1 = (getCeiling(ship.x + 40) + getFloor(ship.x + 40)) / 2;
    const s2 = (getCeiling(ship.x + 100) + getFloor(ship.x + 100)) / 2;
    const s3 = (getCeiling(ship.x + 180) + getFloor(ship.x + 180)) / 2;
    const targetY = s1 * 0.5 + s2 * 0.35 + s3 * 0.15;

    // Proportional-Derivative (PD) steering control
    const error = targetY - ship.y;
    const steeringForce = error * 0.035 - ship.vy * 0.14;
    ship.vy += steeringForce;
    ship.vy = Math.max(-6, Math.min(6, ship.vy));
    ship.y += ship.vy;
    ship.angle = ship.vy * 0.08;

    // Thruster exhaust particles
    particles.push({
      x: ship.x - 12,
      y: ship.y + (Math.random() - 0.5) * 3,
      vx: -(speed * 0.6 + Math.random() * 2),
      vy: (Math.random() - 0.5) * 1.5,
      life: 1.0,
      decay: 0.04 + Math.random() * 0.03
    });

    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= p.decay;
      if (p.life <= 0) particles.splice(i, 1);
    }
  }

  function render() {
    ctx.fillStyle = '#070a14';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    // Grid lines for speed illusion
    ctx.strokeStyle = 'rgba(0, 160, 255, 0.05)';
    ctx.lineWidth = 1;
    const gridOffset = -(distance % 40);
    for (let x = gridOffset; x < WIDTH; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, HEIGHT);
      ctx.stroke();
    }

    // Draw Ceiling
    ctx.fillStyle = '#0e1424';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    for (let x = 0; x <= WIDTH; x += 10) {
      ctx.lineTo(x, getCeiling(x));
    }
    ctx.lineTo(WIDTH, 0);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = '#00e5ff';
    ctx.lineWidth = 3;
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#00e5ff';
    ctx.beginPath();
    for (let x = 0; x <= WIDTH; x += 10) {
      const y = getCeiling(x);
      x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw Floor
    ctx.fillStyle = '#0e1424';
    ctx.beginPath();
    ctx.moveTo(0, HEIGHT);
    for (let x = 0; x <= WIDTH; x += 10) {
      ctx.lineTo(x, getFloor(x));
    }
    ctx.lineTo(WIDTH, HEIGHT);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = '#ff0055';
    ctx.shadowColor = '#ff0055';
    ctx.beginPath();
    for (let x = 0; x <= WIDTH; x += 10) {
      const y = getFloor(x);
      x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();

    ctx.shadowBlur = 0; // Reset glow

    // Scanning Ray from Ship
    ctx.strokeStyle = 'rgba(0, 255, 180, 0.2)';
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y);
    ctx.lineTo(ship.x + 180, (getCeiling(ship.x + 180) + getFloor(ship.x + 180)) / 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // Particles
    particles.forEach(p => {
      ctx.fillStyle = `rgba(255, ${Math.floor(p.life * 180 + 75)}, 40, ${p.life})`;
      ctx.fillRect(p.x, p.y, 3, 3);
    });

    // Ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);

    ctx.shadowBlur = 12;
    ctx.shadowColor = '#00ffc8';
    ctx.fillStyle = '#f0fbff';
    ctx.beginPath();
    ctx.moveTo(14, 0);
    ctx.lineTo(-10, -7);
    ctx.lineTo(-5, 0);
    ctx.lineTo(-10, 7);
    ctx.closePath();
    ctx.fill();

    // Cockpit
    ctx.fillStyle = '#00e5ff';
    ctx.beginPath();
    ctx.arc(0, 0, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // HUD Info
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#a0c4d8';
    ctx.font = '14px Courier New';
    ctx.fillText(`DISTANCE: ${(distance * 0.1).toFixed(0).padStart(6, '0')} m`, 25, 35);
    ctx.fillStyle = '#00ffaa';
    ctx.fillText(`AUTOPILOT: ACTIVE`, 25, 55);
    ctx.fillStyle = '#ffaa00';
    ctx.fillText(`ALTITUDE : ${(HEIGHT - ship.y).toFixed(0)}`, 25, 75);
  }

  function loop() {
    update();
    render();
    requestAnimationFrame(loop);
  }

  loop();
</script>
</body>
</html>
```

The game continually generates an undulating neon cave via overlapping sine waves while an autonomous lookahead PID controller continuously calculates the corridor's center ahead of the ship to steer it smoothly through the passage.
